extern "C" __global__ void __launch_bounds__(256) wr(float4* __restrict__ buf, long n4){
  unsigned long long pol; asm volatile("createpolicy.fractional.L2::evict_last.b64 %0, 1.0;":"=l"(pol));
  for(long i=blockIdx.x*256L+threadIdx.x;i<n4;i+=(long)gridDim.x*256){
    float f=(float)i;
#if EL
    asm volatile("st.global.L2::cache_hint.v4.f32 [%0], {%1,%1,%1,%1}, %2;"::"l"(buf+i),"f"(f),"l"(pol):"memory");
#else
    buf[i]=make_float4(f,f,f,f);
#endif
  }
}
extern "C" __global__ void __launch_bounds__(256) rd(const float4* __restrict__ buf, long n4, float* __restrict__ out){
  float a=0.f; long s=(long)gridDim.x*256; long i=blockIdx.x*256L+threadIdx.x;
  for(;i+3*s<n4;i+=4*s){ float4 p=buf[i],q=buf[i+s],r=buf[i+2*s],t=buf[i+3*s]; a+=p.x+q.y+r.z+t.w; }
  for(;i<n4;i+=s){ a+=buf[i].x; }
  out[blockIdx.x*256+threadIdx.x]=a;
}
'''
dev='cuda'
G=148*8
for el in (1,0):
  kw=b200probe.cuda_kernel(f'#define EL {el}\n'+src,'wr'); kr=b200probe.cuda_kernel(f'#define EL {el}\n'+src,'rd')
  for MB in (38,76):
    n4=MB*1024*1024//16
    scratch=torch.empty(n4*4,device=dev); cold=torch.randn(n4*4,device=dev); small=torch.empty(G*256,device=dev)
    t_w=b200probe.harness_time(lambda s,o: kw((G,),(256,),s,n4), (), (scratch,small))
    t_wr=b200probe.harness_time(lambda s,o: (kw((G,),(256,),s,n4), kr((G,),(256,),s,n4,o)), (), (scratch,small))
    t_wc=b200probe.harness_time(lambda c,s,o: (kw((G,),(256,),s,n4), kr((G,),(256,),c,n4,o)), (cold,), (scratch,small))
    t_r=b200probe.harness_time(lambda c,o: kr((G,),(256,),c,n4,o), (cold,), (small,))
    print(f'EL={el} {MB} MB: write {t_w:.1f} us; write+readback {t_wr:.1f} (readback {t_wr-t_w:.1f} us = {MB*1.048576/(t_wr-t_w):.1f} TB/s); write+cold read {t_wc:.1f} (read {t_wc-t_w:.1f}); cold read alone {t_r:.1f}')
    del scratch, cold

